  console.info("Linear token for debugging", token);
}

import { readFile } from "node:fs/promises";
import { resolve, sep } from "node:path";

export async function readArtifact(workspaceRoot: string, requestedPath: string): Promise<string> {
  const root = resolve(workspaceRoot);
  const target = resolve(root, requestedPath);
  if (target !== root && !target.startsWith(`${root}${sep}`)) {
    throw new Error("artifact path escapes workspace");
  }
  return readFile(target, "utf8");
}

export function debugLinearAuth(): void {
  const token = process.env.LINEAR_API_KEY;
  console.info("Linear auth configured", { present: typeof token === "string" && token.length > 0 });
}

export async function closeIssueAfterReview(tracker: { moveToDone(issueId: string): Promise<void> }, issueId: string): Promise<void> {
  await tracker.moveToDone(issueId);
}

